import { message } from 'antd';
import requestService from 'api/request';
import logo from 'assets/images/logo.png'
import { SubmitHandler, useForm } from 'react-hook-form';
import { useNavigate } from 'react-router-dom';
import { useGlobalAppStore } from 'store/useGlobalApp';

interface IFormInput {
    phone: string;
    password: string;
}

const Login = () => {

    const { loading, handleLoading } = useGlobalAppStore()
    const navigate = useNavigate()
    const { register, handleSubmit, watch, control, setValue, formState: { errors } } = useForm<IFormInput>({
    });

    const onSubmit: SubmitHandler<IFormInput> = async (data) => {
        console.log('====================================');
        console.log(data);
        console.log('====================================');
        handleLoading(true)
        try {
            const res = await requestService.post('/auth/login', {
                data: {
                    ...data
                }
            })
            if (res && res.data) {
                message.success(res?.data?.message)

            }
        } catch (error: any) {
            console.log('====================================');
            console.log(error);
            console.log('====================================');
            message.error(error?.response?.data?.message)
        }
        handleLoading(false)
    };


    return (
        <div data-v-544b5ac9="" data-v-daf86cc3="" className="login-content">
            <div data-v-544b5ac9="" className="login-image flex justify-center">
                <img
                    data-v-544b5ac9=""
                    src={logo}
                    alt="Login"
                    className='rounded-full'
                />
            </div>
            <form data-v-544b5ac9="" className="login-form" onSubmit={handleSubmit(onSubmit)}>
                <div data-v-544b5ac9="" className="form-item">
                    <div data-v-544b5ac9="" className="van-cell van-field">
                        <div className="van-field__left-icon">
                            <div data-v-544b5ac9="" className="country-code">
                                +84
                            </div>
                        </div>
                        {/**/}
                        <div className="van-cell__value van-field__value">
                            <div className="van-field__body">
                                <input
                                    type="tel"
                                    inputMode="numeric"
                                    id="van-field-5-input"
                                    {...register("phone", {
                                        required: "phone_required",
                                        pattern: {
                                            value: /^(0[1-9]\d{8})$|^(0?\d{9})$|^(?:\d{3}[-\s]?\d{3}[-\s]?\d{4})$|^(?:\(\d{3}\)[-\s]?\d{3}[-\s]?\d{4})$/
                                            ,
                                            message: "invalid_phone_number_format"
                                        }

                                    })}
                                    className="van-field__control"
                                    placeholder="Số điện thoại di động"
                                    autoComplete="off"
                                    data-allow-mismatch="attribute"
                                />
                                {/**/}
                                {/**/}
                                {/**/}
                            </div>
                            {/**/}
                            {/**/}
                        </div>
                        {/**/}
                        {/**/}
                    </div>
                    {errors.phone && <p className='pl-2 text-red-600 text-[12px]'>{errors.phone.message}</p>}
                </div>
                <div data-v-544b5ac9="" className="form-item">
                    <div data-v-544b5ac9="" className="van-cell van-field">
                        <div className="van-field__left-icon">
                            <i className="van-badge__wrapper van-icon van-icon-shield-o">
                                {/**/}
                                {/**/}
                                {/**/}
                            </i>
                        </div>
                        {/**/}
                        <div className="van-cell__value van-field__value">
                            <div className="van-field__body">
                                <input
                                    type="password"
                                    id="van-field-6-input"
                                    {...register("password", {
                                        required: "password_required",

                                    })}
                                    className="van-field__control"
                                    placeholder="Mật khẩu"
                                    autoComplete="current-password"
                                    data-allow-mismatch="attribute"
                                />
                                {/**/}
                                <div className="van-field__right-icon">
                                    <i className="van-badge__wrapper van-icon van-icon-closed-eye">
                                        {/**/}
                                        {/**/}
                                        {/**/}
                                    </i>
                                </div>
                                {/**/}
                            </div>
                            {/**/}
                            {/**/}
                        </div>
                        {/**/}
                        {/**/}
                    </div>
                    {errors.password && <p className='pl-2 text-red-600 text-[12px]'>{errors.password.message}</p>}
                </div>

                {/**/}
                <div data-v-544b5ac9="" className="submit-btn">
                    <button
                        data-v-544b5ac9=""
                        type="submit"
                        className="w-full rounded-lg text-[#fff] van-button van-button--primary van-button--normal van-button--block van-button--round van-button--disabled"

                    >
                        <div className="van-button__content">
                            {/**/}
                            <span className="van-button__text">Đăng nhập</span>
                            {/**/}
                        </div>
                    </button>
                </div>
            </form>
        </div>
    )
}

export default Login
